var MISSION_GENERIC_UI=null,MISSION_GENERIC_LOAD=null;
function missionGenericUI(){
  if(MISSION_GENERIC_UI)return Promise.resolve(MISSION_GENERIC_UI);
  if(!MISSION_GENERIC_LOAD)MISSION_GENERIC_LOAD=import('./mission-generic-ui.mjs?v=mission-generic-ui-1.1').then(function(mod){
    MISSION_GENERIC_UI=mod.createMissionUI({client:sb,identity:function(){return !ordinarySigningOut&&loggedIn&&ordinaryAuthId===myId?myId:null;},
      isStaff:function(){return !!iAmStaff;},currentLocation:function(){return cur;},notice:toast,
      refresh:function(){loadMsgs();loadMasterV2();}});return MISSION_GENERIC_UI;
  }).catch(function(e){MISSION_GENERIC_LOAD=null;throw e;});
  return MISSION_GENERIC_LOAD;
}
function missionGenericRoomRefresh(){if(!loggedIn||!sb||!cur||(cur.is_exam_room&&!cur.is_test))return;
  var host=document.getElementById('mission-generic-room');
  missionGenericUI().then(function(ui){return ui.updateRoom(host);}).catch(function(){});
}
